/**
 * Validation Actions
 *
 * HTTP calls to BFF endpoints for flow validation.
 */

import { type AxiosResponse } from 'axios';
import { log4js, logUtil } from '@/utils/logger';
import { apiClient } from '../client';

const logger = log4js.getLogger('validation.actions');

const BFF_HEADERS = {
  'Accept': 'application/json',
  'X-Requested-With': 'XMLHttpRequest',
};

export type ValidationActionType = 'highlight' | 'open_properties' | 'none';

export interface ValidationAlertItem {
  code: string | null;
  message: string | null;
  message_code: string | null;
  node_id: string | null;
  node_name: string | null;
  operator: string | null;
  action_type?: ValidationActionType | null;
}

export interface FlowValidationResponse {
  status: string;
  message: string | null;
  errors: ValidationAlertItem[];
  warnings: ValidationAlertItem[];
}

/**
 * Validate a flow definition via BFF (Elyra format by default)
 *
 * Calls BFF endpoint: POST /api/validation/validate?is_elyra=true
 * BFF proxies to Python backend: POST /api/v1/validation/validate_flow?is_elyra=true
 *
 * The backend validate_flow endpoint (when is_elyra=true) expects:
 *   { "name": "<any string>", "definition": <raw Elyra PipelineFlowDef> }
 * matching the ElyraFlowCreateRequest DTO shape.
 */
export const validateFlow = async (
  flowDefinition: object,
  isElyra = true
): Promise<AxiosResponse<FlowValidationResponse>> => {
  const url = `/api/validation/validate?is_elyra=${isElyra}`;

  // Wrap the raw Elyra pipeline JSON in the ElyraFlowCreateRequest shape
  // that the backend validate_flow endpoint expects when is_elyra=true.
  const body = isElyra
    ? { name: 'validate', definition: flowDefinition }
    : flowDefinition;

  try {
    const response = await apiClient.post<FlowValidationResponse>(url, body, {
      headers: BFF_HEADERS,
    });

    logUtil.info({
      logger,
      message: 'Flow validation completed',
      data: {
        status: response.data.status,
        errors: response.data.errors.length,
        warnings: response.data.warnings.length,
      },
    });

    return response;
  } catch (error) {
    logUtil.error({ logger, message: 'Flow validation request failed', data: error });
    throw error;
  }
};

import { describe, it, expect } from 'vitest';
import { server } from '../../../../mocks/server';
import { http, HttpResponse } from 'msw';
import {
  createProject,
  getProjects,
  getProject,
  replaceProject,
  deleteProject,
} from '@/services/api/actions/project-actions';

describe('project-actions', () => {
  describe('createProject', () => {
    it('happy path: returns created project', async () => {
      const res = await createProject({ name: 'New Project', tags: [] });
      expect(res.status).toBe(201);
      expect(res.data.project_id).toBeDefined();
    });

    it('throws on network error', async () => {
      server.use(
        http.post('/api/projects', () => HttpResponse.error())
      );
      await expect(createProject({ name: 'X' })).rejects.toThrow();
    });

    it('throws on 4xx', async () => {
      server.use(
        http.post('/api/projects', () =>
          HttpResponse.json({ detail: 'Conflict' }, { status: 409 })
        )
      );
      await expect(createProject({ name: 'X' })).rejects.toBeDefined();
    });
  });

  describe('getProjects', () => {
    it('happy path: returns paginated projects', async () => {
      const res = await getProjects();
      expect(res.data.projects).toBeDefined();
    });
  });

  describe('getProject', () => {
    it('happy path: returns a single project', async () => {
      const res = await getProject('project-1');
      expect(res.data.project_id).toBe('project-1');
    });

    it('throws on 404', async () => {
      server.use(
        http.get('/api/projects/:id', () =>
          HttpResponse.json({ detail: 'Not Found' }, { status: 404 })
        )
      );
      await expect(getProject('missing')).rejects.toBeDefined();
    });
  });

  describe('replaceProject', () => {
    it('happy path: returns updated project', async () => {
      server.use(
        http.put('/api/projects/:id', ({ params }) =>
          HttpResponse.json({ project_id: params['id'], name: 'Updated', description: null, tags: [], flow_count: 0, created_on: '', modified_on: '', created_by: null, modified_by: null, href: null })
        )
      );
      const res = await replaceProject('project-1', { name: 'Updated', tags: [] });
      expect(res.data.name).toBe('Updated');
    });
  });

  describe('deleteProject', () => {
    it('happy path: returns 204', async () => {
      const res = await deleteProject('project-1');
      expect(res.status).toBe(204);
    });
  });
});

